import React from 'react';
import { useSelector } from 'react-redux';

const AuthDebug = () => {
  const { user, profile, isAuthenticated, loading, error } = useSelector((state) => state.auth);

  if (process.env.NODE_ENV === 'production') {
    return null;
  }

  return (
    <div className="fixed bottom-4 right-4 bg-black bg-opacity-80 text-white p-4 rounded-lg text-xs max-w-sm z-50">
      <div className="font-bold mb-2">Auth Debug</div>
      <div>Loading: {loading ? 'Yes' : 'No'}</div>
      <div>Authenticated: {isAuthenticated ? 'Yes' : 'No'}</div>
      <div>User ID: {user?.id || 'None'}</div>
      <div>User Email: {user?.email || 'None'}</div>
      <div>Profile: {profile ? 'Loaded' : 'None'}</div>
      <div>User Type: {profile?.user_type || 'Unknown'}</div>
      <div>Profile Name: {profile?.full_name || 'Unknown'}</div>
      {error && <div className="text-red-300">Error: {error}</div>}
    </div>
  );
};

export default AuthDebug;
